package dev.mineagent.runtime.core.config;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class ModelCapabilityTargetTest {
    private final UUID world=UUID.randomUUID(),agent=UUID.randomUUID();
    private Map<String,String> settings(){return new HashMap<>(Map.of("provider.priority","ollama,openai-compatible","provider.ollama.enabled","true","provider.ollama.baseUrl","http://127.0.0.1:11434/","provider.ollama.model","local-model","provider.openai.enabled","true","provider.openai.baseUrl","https://fixture.example/v1/","provider.openai.model","remote-model"));}
    @Test void settingsFollowTheActualDefaultProviderAndAcceptItsCustomModelId(){var values=settings();var target=ModelCapabilityTarget.select(values,world,agent,"","");assertEquals("ollama",target.kind());assertEquals("local-model",target.model());assertEquals("http://127.0.0.1:11434/",target.profile().baseUrl());assertEquals("local-custom",ModelCapabilityTarget.select(values,world,agent,"local-custom","").model());}
    @Test void explicitVisionRoleOverridesDefaultWithoutChangingChat(){var values=settings();values.put("provider.openai.role.vision","remote-vision");assertEquals("ollama",ModelCapabilityTarget.select(values,world,agent,"","").kind());var target=ModelCapabilityTarget.select(values,world,agent,"","vision");assertEquals("openai-compatible",target.kind());assertEquals("remote-vision",target.model());assertEquals("ollama",ModelCapabilityTarget.select(values,world,agent,"local-model","vision").kind());values.put("provider.openai.enabled","false");assertThrows(IllegalStateException.class,()->ModelCapabilityTarget.select(values,world,agent,"","vision"));}
    @Test void anAgentOverrideCannotSilentlyMoveToAnotherServer()throws Exception{var values=settings();var choice=new AgentModelSettings.Choice(world,agent,"CUSTOM","custom","https://fixture.example/v1/",1);values.put("ai.model."+world+"."+agent,new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(choice));assertEquals("custom",ModelCapabilityTarget.select(values,world,agent,"","").model());values.put("provider.openai.baseUrl","https://other.example/v1/");assertThrows(IllegalStateException.class,()->ModelCapabilityTarget.select(values,world,agent,"",""));}
}
